<?php

namespace App\Services\Voice;

use Illuminate\Support\Str;

/**
 * One outbound call the dispatcher asks the switch to place.
 *
 * The reference is generated by OmniCast before the call is originated, so the
 * dialplan and the callbacks the switch posts back can always be correlated
 * even when the provider has not assigned a call id yet.
 */
final class VoiceCall
{
    public function __construct(
        public readonly string $reference,
        public readonly string $to,
        public readonly string $from,
        public readonly string $script,
        public readonly ?string $recordingPath = null,
        public readonly ?VoiceIvrPlan $ivr = null,
        public readonly int $maxDurationSeconds = 60,
    ) {}

    /**
     * The variables the dialplan reads to play the audio and run the IVR menu.
     *
     * @return array<string, string>
     */
    public function variables(): array
    {
        $variables = [
            'OMNICAST_CALL' => $this->reference,
            'OMNICAST_CALLER_ID' => $this->from,
            'OMNICAST_SCRIPT' => Str::limit($this->singleLine($this->script), 900, ''),
            'OMNICAST_RECORDING' => $this->recordingPath,
            'OMNICAST_MAX_DURATION' => (string) $this->maxDurationSeconds,
        ];

        foreach ($this->ivr?->variables() ?? [] as $name => $value) {
            $variables[$name] = $value;
        }

        return array_filter(
            $variables,
            fn (?string $value): bool => $value !== null && $value !== '',
        );
    }

    /**
     * A variable value is a single AMI header or JSON string, never a new line.
     */
    protected function singleLine(string $value): string
    {
        return trim(preg_replace('/\s+/', ' ', $value) ?? '');
    }
}
